inputs = ['zx', 'jv', 'idj', 'idffhc', 'cuh']
outputs = ['gyx', 'wfxv', 'ijxwfx', 'ijxffhc', 'cuh']

# Analyzing each transformation more carefully
print("Detailed analysis:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"Example {i}: '{inp}' -> '{outp}'")

    # Find differences character by character
    min_len = min(len(inp), len(outp))
    diff_positions = []
    for j in range(min_len):
        if inp[j] != outp[j]:
            diff_positions.append((j, inp[j], outp[j]))

    if len(outp) > len(inp):
        # Added characters
        for j in range(min_len, len(outp)):
            diff_positions.append((j, '_', outp[j]))
    elif len(inp) > len(outp):
        # Removed characters  
        for j in range(min_len, len(inp)):
            diff_positions.append((j, inp[j], '_'))

    print(f"  Differences: {diff_positions}")
    print()

